    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    def flood(r0,c0):
        stack=[(r0,c0)]; seen={(r0,c0)}; ret=[]
        while stack:
            r,c=stack.pop(); ret.append((r,c))
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]==0 and (nr,nc) not in seen:
                    seen.add((nr,nc)); stack.append((nr,nc))
        return ret
    for comp in flood(range(H), lambda c:[c]): pass
    comps=[]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                cs=flood(i,j); seen[i][j]=True
                cols={c for _,c in cs}; rs=[r for r,_ in cs]
                comps.append((rs,cols))
    out=g
    for rs,cols in comps:
        rmin,rmax=min(rs),max(rs); cmin,cmax=min(cols),max(cols)
        # fill interior (0 cells inside bbox, strictly between border)
        for r in range(rmin+1,rmax):
            for c in range(cmin+1,cmax):
                if out[r][c]==0: out[r][c]=2
        # bar: cols cmin-1..cmax (length == height? demo: bar width-1 ... rect 2..5 w4, bar 1..4 len4 same as width)
        bar_start=cmin-1; bar_len=(cmax-cmin+1)
        for c in range(bar_start,bar_start+bar_len):
            if rmin-1>=0 and 0<=c<W: out[rmin-1][c]=2
    return out
